type (
	// Filter is the interface that wraps the Where function
	// for filtering nodes in queries and mutations.
	Filter interface {
		// Where applies a filter on the executed query/mutation.
		Where(entql.P)
	}

	// The FilterFunc type is an adapter that allows the use of ordinary
	// functions as filters for query and mutation types.
	FilterFunc func(context.Context, Filter) error
)

// EvalQuery calls f(ctx, q) if the query implements the Filter interface, otherwise it is denied.
func (f FilterFunc) EvalQuery(ctx context.Context, q ent.Query) error {
	fr, err := queryFilter(q)
	if err != nil {
		return err
	}
	return f(ctx, fr)
}

// EvalMutation calls f(ctx, q) if the mutation implements the Filter interface, otherwise it is denied.
func (f FilterFunc) EvalMutation(ctx context.Context, m ent.Mutation) error {
	fr, err := mutationFilter(m)
	if err != nil {
		return err
	}
	return f(ctx, fr)
}

var _ QueryMutationRule = FilterFunc(nil)

func queryFilter(q ent.Query) (Filter, error) {
	switch q := q.(type) {
	case *ent.AccessChangeQuery:
		return q.Filter(), nil
	case *ent.AgentQuery:
		return q.Filter(), nil
	case *ent.AppRoleQuery:
		return q.Filter(), nil
	case *ent.ApplicationQuery:
		return q.Filter(), nil
	case *ent.ClientAssertionJTIQuery:
		return q.Filter(), nil
	case *ent.ConsentGrantQuery:
		return q.Filter(), nil
	case *ent.CredentialQuery:
		return q.Filter(), nil
	case *ent.ExternalIdentityQuery:
		return q.Filter(), nil
	case *ent.HumanQuery:
		return q.Filter(), nil
	case *ent.InviteQuery:
		return q.Filter(), nil
	case *ent.LicenseQuery:
		return q.Filter(), nil
	case *ent.ListingQuery:
		return q.Filter(), nil
	case *ent.LoginSessionQuery:
		return q.Filter(), nil
	case *ent.LoginStateQuery:
		return q.Filter(), nil
	case *ent.ManagerClaimQuery:
		return q.Filter(), nil
	case *ent.ManagerInviteQuery:
		return q.Filter(), nil
	case *ent.ManagerRelationshipQuery:
		return q.Filter(), nil
	case *ent.OAuthAppQuery:
		return q.Filter(), nil
	case *ent.OAuthAppSecretQuery:
		return q.Filter(), nil
	case *ent.OAuthAuthCodeQuery:
		return q.Filter(), nil
	case *ent.OAuthConsentQuery:
		return q.Filter(), nil
	case *ent.OAuthTokenQuery:
		return q.Filter(), nil
	case *ent.OrganizationQuery:
		return q.Filter(), nil
	case *ent.PrincipalQuery:
		return q.Filter(), nil
	case *ent.PrincipalMembershipQuery:
		return q.Filter(), nil
	case *ent.PrincipalTokenQuery:
		return q.Filter(), nil
	case *ent.ResourceGrantQuery:
		return q.Filter(), nil
	case *ent.SeatAssignmentQuery:
		return q.Filter(), nil
	case *ent.ServicePrincipalQuery:
		return q.Filter(), nil
	case *ent.SlugReservationQuery:
		return q.Filter(), nil
	case *ent.SubscriptionQuery:
		return q.Filter(), nil
	default:
		return nil, Denyf("ent/privacy: unexpected query type %T for query filter", q)
	}
}

